entryFade( spep_1+255, 3, 5, 4, fcolor_r, fcolor_g, fcolor_b, 255);     -- white fade


-- ** エフェクト ** --

kitame = entryEffect( spep_1, SP_01, 0x100, -1,  0,  0,  0);   -- 手のカメハメ波部
